VALID_AGE_GROUPS = ["6-11", "12-17", "18-23", "24-30", "31-40"]

AGE_GROUP_TAG_MAP = {
    "6-11": ["6-11", "6-9", "10-12"],
    "12-17": ["12-17", "13-17"],
    "18-23": ["18-23", "18-25"],
    "24-30": ["24-30", "26-32"],
    "31-40": ["31-40", "33-40"]
}

def get_age_group_id(age_or_group):
    """Normalize input (numeric age or string) into one of the exact 5 FLUENCY age groups: 6-11, 12-17, 18-23, 24-30, 31-40."""
    if not age_or_group:
        return "18-23"
    
    val_str = str(age_or_group).strip().replace("–", "-")
    if val_str in VALID_AGE_GROUPS:
        return val_str
    
    try:
        age = int(val_str)
        if age <= 11:
            return "6-11"
        elif age <= 17:
            return "12-17"
        elif age <= 23:
            return "18-23"
        elif age <= 30:
            return "24-30"
        else:
            return "31-40"
    except (TypeError, ValueError):
        pass
    
    legacy_map = {
        "6-9": "6-11",
        "10-12": "12-17",
        "13-17": "12-17",
        "18-25": "18-23",
        "26-32": "24-30",
        "33-40": "31-40"
    }
    return legacy_map.get(val_str, "18-23")


def get_age_group_label(age_group):
    """Return user-friendly label for the 5 exact age groups."""
    labels = {
        "6-11": "6–11",
        "12-17": "12–17",
        "18-23": "18–23",
        "24-30": "24–30",
        "31-40": "31–40"
    }
    return labels.get(get_age_group_id(age_group), "18–23")



def get_reading_for_age_and_diff(age_group="18-23", difficulty="all", length_type="all"):
    """
    Retrieve curated reading passages for given age group across the 5 core groups (6-11, 12-17, 18-23, 24-30, 31-40),
    difficulty (easy, medium, hard), and length (short, medium, long).
    Ensures that Easy, Medium, and Hard difficulty are strictly RELATIVE to the specific age group.
    """
    normalized_group = get_age_group_id(age_group)
    
    diff = (difficulty or "all").lower().strip()
    diff_map = {
        "easy": "easy", "beginner": "easy",
        "medium": "medium", "intermediate": "medium",
        "hard": "hard", "advanced": "hard"
    }
    if diff in diff_map:
        diff = diff_map[diff]
    
    len_type = (length_type or "all").lower().strip()
    
    # Strictly filter by the normalized age group
    filtered = [i for i in READING_CONTENT if i.get("age_group") == normalized_group]
    if not filtered:
        filtered = [i for i in READING_CONTENT if i.get("age_group") == "18-23"]
    
    if diff != "all":
        filtered = [i for i in filtered if i.get("difficulty") == diff]
        
    if len_type != "all":
        filtered = [i for i in filtered if i.get("length_type") == len_type]
        
    return filtered


def get_videos_for_age_and_diff(age_group="18-23", difficulty="all"):
    """Retrieve curated videos for given age group across the 5 core groups (6-11, 12-17, 18-23, 24-30, 31-40) and difficulty."""
    normalized_group = get_age_group_id(age_group)
    match_tags = set(AGE_GROUP_TAG_MAP.get(normalized_group, ["18-23", "18-25"]))
    
    diff = (difficulty or "all").lower().strip()
    diff_map = {
        "easy": "Easy", "beginner": "Easy",
        "medium": "Medium", "intermediate": "Medium",
        "hard": "Hard", "advanced": "Hard"
    }

    filtered = [v for v in VIDEO_PRACTICE_ITEMS if v.get("age_group") in match_tags]
    if not filtered:
        filtered = [v for v in VIDEO_PRACTICE_ITEMS if v.get("age_group") in ["18-23", "18-25"]]
    
    if diff != "all" and diff in diff_map:
        target = diff_map[diff]
        filtered = [v for v in filtered if v.get("difficulty") == target]
    
    return filtered


def get_images_for_age_and_diff(age_group="18-23", difficulty="all"):
    """Retrieve curated images for given age group across the 5 core groups (6-11, 12-17, 18-23, 24-30, 31-40) and difficulty."""
    normalized_group = get_age_group_id(age_group)
    match_tags = set(AGE_GROUP_TAG_MAP.get(normalized_group, ["18-23", "18-25"]))
    
    diff = (difficulty or "all").lower().strip()
    diff_map = {
        "easy": "Easy", "beginner": "Easy",
        "medium": "Medium", "intermediate": "Medium",
        "hard": "Hard", "advanced": "Hard"
    }

    filtered = [i for i in IMAGE_PRACTICE_ITEMS if i.get("age_group") in match_tags]
    if not filtered:
        filtered = [i for i in IMAGE_PRACTICE_ITEMS if i.get("age_group") in ["18-23", "18-25"]]
    
    if diff != "all" and diff in diff_map:
        target = diff_map[diff]
        filtered = [i for i in filtered if i.get("difficulty") == target]
    
    return filtered


