def get_therapy_videos(category="all", query=""):
    """Retrieve filtered therapy videos by category or search term."""
    items = THERAPY_VIDEOS
    cat = (category or "all").lower().strip()
    if cat != "all":
        items = [v for v in items if v.get("category_key", "").lower() == cat]
    
    q = (query or "").lower().strip()
    if q:
        items = [
            v for v in items
            if q in v.get("title", "").lower()
            or q in v.get("description", "").lower()
            or q in v.get("source", "").lower()
            or q in v.get("category", "").lower()
        ]
    return items


