def get_tongue_twisters(difficulty="all", category="all"):
    """Retrieve tongue twisters filtered by difficulty or focus."""
    items = TONGUE_TWISTERS
    diff = (difficulty or "all").lower().strip()
    if diff != "all":
        items = [t for t in items if t.get("difficulty", "").lower() == diff]
    
    cat = (category or "all").lower().strip()
    if cat != "all":
        items = [t for t in items if cat in t.get("focus_sound", "").lower() or cat in t.get("title", "").lower()]
    return items


